import React from 'react';

const SignupVisual = () => {
    return (
        <div className="relative flex flex-col justify-end p-8 md:p-12 overflow-hidden bg-primary w-full h-full group">
            <div className="absolute inset-0">
                <img 
                    alt="Enterprise environment" 
                    className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" 
                    src="https://lh3.googleusercontent.com/aida-public/AB6AXuCRAE9EjTILC5RU9UCaghGHXgZBFWsR1bCfE9XL4un_VF6KGCeoptArTLBEe8_fTLopRRa-CRgSNUUbrxfRX2g9M11HozJX3RYH5_0gbKOskKgdipzWU7UfngnEYUthSXRpmn03YbP3eUHNsnOOzn2KMPjEDqh-pf-Dp4-f6idKUvD_gK7a52unugOJwliWGfHaVdl3ZvyUBR9sTSaEUPwA_ydoTzWYVWtW9QChP9bW6y28kSEgwJvznI-Om3IqaE0A0lRkDEQRzkM"
                />
                {/* Premium Gradient Overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-black/10"></div>
            </div>
            <div className="relative z-10 transform transition-all duration-500 translate-y-0 group-hover:-translate-y-2">
                <h1 className="font-display-lg text-[32px] md:text-display-lg text-white mb-3 md:mb-4 drop-shadow-md leading-tight">Precision at scale.</h1>
                <p className="font-body-md md:font-body-lg text-body-md md:text-body-lg text-white/90 max-w-md drop-shadow">Join thousands of professional operators who trust The Entrance for high-stakes data integrity and secure infrastructure.</p>
                <div className="mt-6 md:mt-8 flex gap-4">
                    <div className="flex items-center gap-2 px-4 py-2 bg-white/10 backdrop-blur-md rounded-full border border-white/20 shadow-lg transition-colors hover:bg-white/20 cursor-default">
                        <span className="material-symbols-outlined text-white text-[20px]" data-icon="verified_user">verified_user</span>
                        <span className="font-label-sm md:font-label-md text-label-sm md:text-label-md text-white">ISO 27001 Certified</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SignupVisual;
